from fractions import Fraction

def exact_survival(m: int, k: int) -> Fraction:
    if m <= 0 or k < 0:
        raise ValueError("Require m > 0 and k >= 0")
    return Fraction(2**m - 1, 2**m) ** k

for m, k in [(3, 10), (10, 1000), (20, 1000)]:
    value = exact_survival(m, k)
    print(m, k, float(value))

def histogram(q: int, secret: int) -> list[int]:
    if q <= 0:
        raise ValueError("q must be positive")
    counts = [0] * q
    for mask in range(q):
        counts[(secret + mask) % q] += 1
    return counts

q = 11
rows = [histogram(q, secret) for secret in range(q)]
print("all distributions uniform and equal:", all(row == [1] * q for row in rows))

