from itertools import product
from typing import Callable

Valuation = tuple[bool, ...]

def exhaustive_acceptance_count(m: int, evaluate: Callable[[Valuation], bool]) -> int:
    if m < 0:
        raise ValueError("m must be nonnegative")
    return sum(1 for v in product((False, True), repeat=m) if evaluate(v))

from math import ceil, log, log1p

def minimum_repetitions(m: int, epsilon: float) -> int:
    if m <= 0 or not 0.0 < epsilon < 1.0:
        raise ValueError("Require m > 0 and 0 < epsilon < 1")
    return ceil(log(epsilon) / log1p(-(2.0 ** -m)))

def additive_mask_table(q: int) -> list[list[int]]:
    if q <= 0:
        raise ValueError("q must be positive")
    return [[(secret + mask) % q for mask in range(q)] for secret in range(q)]

def audit_uniformity(q: int) -> bool:
    target = list(range(q))
    return all(sorted(row) == target for row in additive_mask_table(q))

